INSERT INTO figures (id, name, name_alt, years, era, region, role, tags, bio, relation, story, image, mds, dlabels, dkinds, note, relations, rel_notes) VALUES
  (31, '弗里达·卡罗', 'Frida Kahlo', '1907—1954', '20世纪', '墨西哥', '画家', ARRAY['画家', '墨西哥', '自画像'], '墨西哥画家，以充满疼痛与身份思考的自画像闻名。她将个人苦难与民族符号结合，成为女性艺术的象征。', '病友', '', 'assets/figures/kahlo.jpg', ARRAY['07-06', '09-13'], ARRAY['诞辰 · 1907年7月6日', '与里维拉结婚 · 1929年9月13日'], ARRAY['birth', 'event'], '她画了一百四十三个自己，谁也替不了她画那张脸。', ARRAY['病友', '画框师傅'], ARRAY['她画了一百四十三个自己，谁也替不了她画那张脸。', '她长年卧病，陪床、扶她起身、替她绷画框的是你。']),
  (32, '沃尔夫冈·阿马德乌斯·莫扎特', 'Wolfgang Amadeus Mozart', '1756—1791', '18世纪', '奥地利', '作曲家', ARRAY['音乐家', '奥地利', '古典'], '奥地利作曲家，古典主义音乐的巅峰人物。他幼年为神童，一生写下六百余部作品，旋律天赋空前绝后。', '乐团同人', '', 'assets/figures/mozart.jpg', ARRAY['01-27', '10-02'], ARRAY['诞辰 · 1756年1月27日', '《魔笛》首演 · 1791年10月2日'], ARRAY['birth', 'event'], '同行早就习惯了他的排练方式，和他永远差半拍。', ARRAY['乐团同人', '抄谱员'], ARRAY['同行早就习惯了他的排练方式，和他永远差半拍。', '他写谱快得离谱，坐在旁边替他誊清分谱的那个人是你。']),
  (33, '路德维希·凡·贝多芬', 'Ludwig van Beethoven', '1770—1827', '18—19世纪', '德国', '作曲家', ARRAY['音乐家', '德国', '古典'], '德国作曲家，连接古典与浪漫的桥梁。他在渐失听力后仍写出《第九交响曲》，以音乐宣告对命运的搏击。', '同屋租客', '', 'assets/figures/beethoven.jpg', ARRAY['12-16', '05-07'], ARRAY['诞辰 · 1770年12月16日', '《第九交响曲》首演 · 1824年5月7日'], ARRAY['birth', 'event'], '他的耳聋越来越重，脾气越来越坏，房租却一次没欠过。', ARRAY['同屋租客', '调律师傅'], ARRAY['他的耳聋越来越重，脾气越来越坏，房租却一次没欠过。', '他的钢琴走音他听不出来，每次都是你悄悄替他调好。']),
  (34, '弗雷迪·默丘里', 'Freddie Mercury', '1946—1991', '20世纪', '英国', '歌手', ARRAY['音乐家', '英国', '摇滚'], '英国摇滚乐队皇后乐队的主唱，以华丽舞台与广阔音域著称。他是20世纪最具表现力的表演者之一。', '经纪人', '', 'assets/figures/freddie.jpg', ARRAY['09-05', '07-13'], ARRAY['诞辰 · 1946年9月5日', 'Live Aid · 1985年7月13日'], ARRAY['birth', 'event'], '他的曲目单里，永远排着最后一首安可。', ARRAY['经纪人', '巡演司机'], ARRAY['他的曲目单里，永远排着最后一首安可。', '他巡演从不管路线，握着方向盘把他送到下一场的是你。']),
  (35, '威廉·莎士比亚', 'William Shakespeare', '1564—1616', '16—17世纪', '英国', '剧作家', ARRAY['文学家', '英国', '戏剧'], '英国剧作家与诗人，被广泛视为英语文学最伟大的作家。他留下三十七部戏剧与大量十四行诗，塑造了无数经典形象。', '剧院同事', '', 'assets/figures/shakespeare.jpg', ARRAY['04-23', '11-19'], ARRAY['诞辰 · 1564年4月23日', '《第一对开本》出版 · 1623年11月19日'], ARRAY['birth', 'event'], '他在剧院里既写剧本又上台演戏，还替贵族管账——你们是同事。', ARRAY['剧院同事', '戏服裁缝'], ARRAY['他在剧院里既写剧本又上台演戏，还替贵族管账——你们是同事。', '环球剧场的戏服你一针一线缝，他谢幕时总朝你那厢点头。']),
  (36, '简·奥斯汀', 'Jane Austen', '1775—1817', '18—19世纪', '英国', '小说家', ARRAY['文学家', '英国', '小说'], '英国小说家，以《傲慢与偏见》等六部小说刻画乡绅阶层的婚恋与世相，以讽刺与细腻的心理描写著称。', '书友', '', 'assets/figures/austen.jpg', ARRAY['12-16', '01-28'], ARRAY['诞辰 · 1775年12月16日', '《傲慢与偏见》出版 · 1813年1月28日'], ARRAY['birth', 'event'], '她一辈子没结婚，笔下的人物却全在谈恋爱。', ARRAY['书友', '乡间舞伴'], ARRAY['她一辈子没结婚，笔下的人物却全在谈恋爱。', '乡间舞会上她总坐边上看，陪她聊完一整场的是你。']),
  (37, '埃德加·爱伦·坡', 'Edgar Allan Poe', '1809—1849', '19世纪', '美国', '诗人 · 小说家', ARRAY['文学家', '美国', '哥特'], '美国诗人、小说家与评论家，推理小说与哥特风格的先驱。《乌鸦》与《莫格街凶杀案》影响深远。', '笔友', '', 'assets/figures/poe.jpg', ARRAY['01-19', '01-26'], ARRAY['诞辰 · 1809年1月19日', '《乌鸦》发表 · 1845年1月26日'], ARRAY['birth', 'event'], '他从巴尔的摩写信到欧洲，收信的人没有一个睡得着觉。', ARRAY['笔友', '杂志校对'], ARRAY['他从巴尔的摩写信到欧洲，收信的人没有一个睡得着觉。', '他办的刊物你做校对，红笔圈出的错字比他还狠。']),
  (38, '查尔斯·狄更斯', 'Charles Dickens', '1812—1870', '19世纪', '英国', '小说家', ARRAY['文学家', '英国', '小说'], '英国维多利亚时代最伟大的小说家。他以《雾都孤儿》《双城记》等揭露社会不公，连载形式让小说走近大众。', '合租室友', '', 'assets/figures/dickens.jpg', ARRAY['02-07', '12-19'], ARRAY['诞辰 · 1812年2月7日', '《圣诞颂歌》出版 · 1843年12月19日'], ARRAY['birth', 'event'], '他白天写社论晚上写小说，稿酬从来没乱花过。', ARRAY['合租室友', '报社抄写'], ARRAY['他白天写社论晚上写小说，稿酬从来没乱花过。', '他早年贫苦，在报社当学徒抄写，同铺的工友是你。']),
  (39, '维克多·雨果', 'Victor Hugo', '1802—1885', '19世纪', '法国', '作家', ARRAY['文学家', '法国', '小说'], '法国浪漫主义文学的领袖，《巴黎圣母院》《悲惨世界》的作者。他也是一位积极介入公共生活的政治家。', '笔友', '', 'assets/figures/hugo.jpg', ARRAY['02-22', '12-11'], ARRAY['诞辰 · 1802年2月22日', '结束流亡返国 · 1870年12月11日'], ARRAY['birth', 'event'], '流亡十九年，他把《悲惨世界》写完了，回国那天的船上全是人。', ARRAY['笔友', '流亡船工'], ARRAY['流亡十九年，他把《悲惨世界》写完了，回国那天的船上全是人。', '他流亡到盖纳西岛，摆渡接信、运书箱的那条船归你摇。']),
  (40, '奥斯卡·王尔德', 'Oscar Wilde', '1854—1900', '19世纪', '爱尔兰', '作家', ARRAY['文学家', '爱尔兰', '喜剧'], '爱尔兰作家与剧作家，以机智的警句与《道林·格雷的画像》《不可儿戏》闻名，是唯美主义的代表。', '饭友', '', 'assets/figures/wilde.jpg', ARRAY['10-16', '04-05'], ARRAY['诞辰 · 1854年10月16日', '《道林·格雷》出版 · 1890年4月5日'], ARRAY['birth', 'event'], '他机智到把法庭变成舞台，却把最好的位置留给了饭友。', ARRAY['饭友', '美学沙龙主'], ARRAY['他机智到把法庭变成舞台，却把最好的位置留给了饭友。', '他在巴黎办美学沙龙，端茶、引座、替他挡掉无趣访客的是你。'])
